import{_ as i,o as e,c as a,a2 as o}from"./chunks/framework.CdvW4CUT.js";const n=JSON.parse('{"title":"簡易小功能","description":"一些伺服開發的小功能，能提升遊玩的便利性或趣味性。","frontmatter":{"title":"簡易小功能","description":"一些伺服開發的小功能，能提升遊玩的便利性或趣味性。"},"headers":[],"relativePath":"feature/simple/index.md","filePath":"feature/simple.md"}'),t={name:"feature/simple/index.md"};function r(d,l,c,u,h,s){return e(),a("div",null,[...l[0]||(l[0]=[o('<h1 id="簡易小功能" tabindex="-1">簡易小功能 <a class="header-anchor" href="#簡易小功能" aria-label="Permalink to &quot;簡易小功能&quot;">​</a></h1><h2 id="骰子" tabindex="-1">骰子 <a class="header-anchor" href="#骰子" aria-label="Permalink to &quot;骰子&quot;">​</a></h2><ul><li><code>/roll &lt;點數最小值&gt; &lt;點數最大值&gt; &lt;重複次數&gt;</code><b>依照設定擲出骰子</b><ul><li>很簡單的隨機數獲取，可以用來賭博或當抽籤用</li><li>使用此功能需消耗<code>青金石</code>，請手持青金石才可操作</li><li>可自由設定點數最小值/最大值和重複次數 <ul><li>皆需輸入整數</li><li>若未輸入最小值與最大值，預設範圍為<code>1-6</code><ul><li>若需要設定範圍，請同時輸入最小值與最大值</li></ul></li><li>最小值需<code>&gt;=1</code>且最大值需<code>&lt;=2147483647</code></li><li>重複次數需<code>&lt;=10</code>，輸出時會顯示數值加總</li></ul></li><li>當你骰下去後 你<code>半徑20格內</code>的玩家會收到此訊息</li><li>將游標移動至骰子結果上，可查看該次擲骰的詳細訊息<br><img src="https://i.imgur.com/oBpWggG.png" style="width:50%;"></li><li><a href="/feature/roll_raw/">骰子指令原始碼</a></li></ul></li></ul><h3 id="指令示範" tabindex="-1">指令示範 <a class="header-anchor" href="#指令示範" aria-label="Permalink to &quot;指令示範&quot;">​</a></h3><ul><li><code>/roll</code><ul><li>骰出 <code>1顆</code> <code>1-6</code> 的骰子<br><img src="https://i.imgur.com/Cx6b0gQ.png" style="width:50%;"></li></ul></li><li><code>/roll 1 20</code><ul><li>骰出 <code>1顆</code> <code>1-20</code> 的骰子<br><img src="https://i.imgur.com/vrtovRo.png" style="width:50%;"></li></ul></li><li><code>/roll 1 6 3</code><ul><li>骰出 <code>3顆</code> <code>1-6</code> 的骰子 (消耗<code>3顆</code>青金石)<br><img src="https://i.imgur.com/8Hzun0w.png" style="width:50%;"></li></ul></li></ul><h2 id="開啟官網及新手教學連結" tabindex="-1">開啟官網及新手教學連結 <a class="header-anchor" href="#開啟官網及新手教學連結" aria-label="Permalink to &quot;開啟官網及新手教學連結&quot;">​</a></h2><ul><li><code>/rule</code><b>在聊天欄顯示官網及新手教學頁面連結</b>(<code>/rules</code>也是同樣效果)</li></ul><h2 id="pvp" tabindex="-1">PVP <a class="header-anchor" href="#pvp" aria-label="Permalink to &quot;PVP&quot;">​</a></h2><ul><li><code>/pvp</code><b>開啟/關閉PVP</b><ul><li>開啟後須冷卻30秒才可關閉 <ul><li>冷卻期間若有攻擊玩家會重製計時</li></ul></li><li>各分流設定不同步</li></ul></li><li><code>/pvp status</code><b>查看PVP狀態</b></li></ul><h2 id="顯示-隱藏玩家頭上的id" tabindex="-1">顯示/隱藏玩家頭上的ID <a class="header-anchor" href="#顯示-隱藏玩家頭上的id" aria-label="Permalink to &quot;顯示/隱藏玩家頭上的ID&quot;">​</a></h2><ul><li><code>/hidename</code><b>顯示/隱藏玩家頭上的ID</b><ul><li>每次<b>隱藏</b>會消耗20元遊戲幣</li><li>各分流設定不同步 <ul><li>分流重開後會重置設定，恢復為顯示</li></ul></li></ul></li></ul><h2 id="主三-設三白名單" tabindex="-1">主三/設三白名單 <a class="header-anchor" href="#主三-設三白名單" aria-label="Permalink to &quot;主三/設三白名單&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">說明</p><p>此功能為<a href="/donate/"><b>贊助玩家</b></a>限定，同時只能在<b>主三</b>或<b>設三</b>使用，詳細請參考<a href="/donate/"><b>贊助頁面</b></a>說明</p></div><ul><li><code>/wl add &lt;玩家ID&gt;</code><b>將指定玩家加入你的白名單列表</b></li><li><code>/wl</code><b>查看你的白名單朋友列表</b></li></ul><h2 id="排除幽靈方塊" tabindex="-1">排除幽靈方塊 <a class="header-anchor" href="#排除幽靈方塊" aria-label="Permalink to &quot;排除幽靈方塊&quot;">​</a></h2><ul><li><code>/ghost</code><b>排除半徑16內的幽靈方塊</b><ul><li>當你遇到幽靈方塊(Ghost Block)的狀況時，這個指令可以幫助你更新你周遭16格球體的方塊，以解決此狀況。</li></ul></li></ul><h2 id="界伏盒開啟" tabindex="-1">界伏盒開啟 <a class="header-anchor" href="#界伏盒開啟" aria-label="Permalink to &quot;界伏盒開啟&quot;">​</a></h2><ul><li>界伏盒可以在背包直接對它按右鍵開啟</li></ul><h2 id="移除界伏盒的nbt標籤及名字" tabindex="-1">移除界伏盒的NBT標籤及名字 <a class="header-anchor" href="#移除界伏盒的nbt標籤及名字" aria-label="Permalink to &quot;移除界伏盒的NBT標籤及名字&quot;">​</a></h2><ul><li><code>/removeboxtag</code><b>移除背包內所有空盒的標籤及名字</b><ul><li>用於商店街交易，避免因標籤問題使商人無法辨識，而無法進行交易</li></ul></li></ul><h2 id="盔甲架保護" tabindex="-1">盔甲架保護 <a class="header-anchor" href="#盔甲架保護" aria-label="Permalink to &quot;盔甲架保護&quot;">​</a></h2><ul><li>將盔甲架保護後，只有你可以修改及對盔甲架造成傷害(但不防其他玩家射箭/縱火) <ul><li><b>設定方式：</b>手持命名牌對盔甲架右鍵(會消耗)，即可完成保護</li><li><b>備註：</b>若你後來更改ID，請透過射箭的方式去移除盔甲架</li></ul></li></ul><h2 id="資訊查看" tabindex="-1">資訊查看 <a class="header-anchor" href="#資訊查看" aria-label="Permalink to &quot;資訊查看&quot;">​</a></h2><h3 id="查詢線上玩家" tabindex="-1">查詢線上玩家 <a class="header-anchor" href="#查詢線上玩家" aria-label="Permalink to &quot;查詢線上玩家&quot;">​</a></h3><ul><li><code>/glist</code><b>在聊天欄顯示上線玩家列表</b><br><img src="https://i.imgur.com/R5wapuE.png" style="width:80%;"></li><li><code>/find</code><b>查詢指定玩家的在線狀態</b><ul><li>在線會顯示在哪個分流，不在會顯示不在線上<br><img src="https://i.imgur.com/UkNhVzX.png" style="width:30%;"><br><img src="https://i.imgur.com/tCFQQDm.png" style="width:30%;"></li></ul></li></ul><h3 id="鐵砧懲罰等級-repaircost" tabindex="-1">鐵砧懲罰等級(repaircost) <a class="header-anchor" href="#鐵砧懲罰等級-repaircost" aria-label="Permalink to &quot;鐵砧懲罰等級(repaircost)&quot;">​</a></h3><ul><li><code>/repaircost</code><b>查詢手上物品的鐵砧懲罰等級(repaircost)</b></li></ul><h3 id="紅磚頭" tabindex="-1">紅磚頭 <a class="header-anchor" href="#紅磚頭" aria-label="Permalink to &quot;紅磚頭&quot;">​</a></h3><ul><li>對蜂巢點右鍵，可查看蜂箱蜜蜂數量與座標</li><li>對海龜點右鍵，可查看海龜重生點在哪(讓海龜下蛋會用到)</li><li>對村民點右鍵，可查看床與工作點的座標</li><li>對可馴服的生物右鍵，可查看該生物的主人</li><li>對可繁殖的生物右鍵，可查看該生物的成年所需時間或交配冷卻時間</li><li>對告示牌右鍵，可查看該告示牌的文字內容</li><li>對任意方塊點右鍵，可以查看該方塊的座標位置</li></ul><h3 id="六角恐龍桶" tabindex="-1">六角恐龍桶 <a class="header-anchor" href="#六角恐龍桶" aria-label="Permalink to &quot;六角恐龍桶&quot;">​</a></h3><ul><li>用水桶撈六角恐龍，可查看顏色及生長階段<br><img src="https://i.imgur.com/oCWQQy7.png" style="width:30%;"></li></ul>',31)])])}const m=i(t,[["render",r]]);export{n as __pageData,m as default};
